+func realTLSState(t *testing.T) tls.ConnectionState {
+	t.Helper()
+	certPEM, keyPEM := selfSignedCert(t)
+	cert, err := tls.X509KeyPair(certPEM, keyPEM)
+	if err != nil {
+		t.Fatalf("build cert: %v", err)
